-- PromptFace — catálogo no banco + escrita só para admin (Fase 1 do painel, 28/11/2026).
--
-- 1. Políticas de escrita: só admin cria/edita/exclui categorias e cenários.
--    A leitura pública já existe desde a migração 1 (categories_select_public /
--    scenarios_select_public). Sem policy de escrita, o RLS nega tudo — por
--    isso o painel estava pausado.
-- 2. Sincronização: o banco passa a ter o catálogo EXATAMENTE como está em
--    src/shared/catalog.ts (14 categorias, 84 cenários). Apaga e reinsere
--    tudo na mesma transação. Nenhuma outra tabela referencia categories ou
--    scenarios por FK, então o DELETE é seguro.

-- categorias: o admin cria, edita e exclui.
drop policy if exists "categories_insert_admin" on public.categories;
create policy "categories_insert_admin" on public.categories
  for insert to authenticated
  with check (public.is_admin());

drop policy if exists "categories_update_admin" on public.categories;
create policy "categories_update_admin" on public.categories
  for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

drop policy if exists "categories_delete_admin" on public.categories;
create policy "categories_delete_admin" on public.categories
  for delete to authenticated
  using (public.is_admin());

-- cenários: o admin cria, edita e exclui.
drop policy if exists "scenarios_insert_admin" on public.scenarios;
create policy "scenarios_insert_admin" on public.scenarios
  for insert to authenticated
  with check (public.is_admin());

drop policy if exists "scenarios_update_admin" on public.scenarios;
create policy "scenarios_update_admin" on public.scenarios
  for update to authenticated
  using (public.is_admin())
  with check (public.is_admin());

drop policy if exists "scenarios_delete_admin" on public.scenarios;
create policy "scenarios_delete_admin" on public.scenarios
  for delete to authenticated
  using (public.is_admin());

-- Sincronização do catálogo (gerado a partir de src/shared/catalog.ts em 2026-11-28).
-- Apaga e reinsere tudo na mesma transação: o banco fica idêntico ao código.
begin;
delete from public.scenarios;
delete from public.categories;
commit;
